const show=()=>{const rate=+inputRate.value,n=+tasks.value,epoch=+epochMs.value,capacity=n*8000,eligible=!stateful.checked,util=100*rate/capacity;world.textContent='Spark 4.1 RTM eligibility in this toy: '+(eligible?'ELIGIBLE stateless shape':'INELIGIBLE: keyed state requested')+'
Capacity estimate: '+capacity.toLocaleString()+' events/s
Input: '+rate.toLocaleString()+' events/s | utilization: '+util.toFixed(0)+'%
Approximate batching wait: '+(epoch/2).toFixed(1)+' ms
Outcome: '+(!eligible?'Choose a supported stateful execution path or split the graph.':util>100?'OVERLOADED: epochs cannot drain sustained input.':'Capacity headroom exists; validate end-to-end behavior.')};[inputRate,tasks,epochMs,stateful].forEach(e=>e.oninput=show);show();
function drawMechanism(){const rate=+inputRate.value,n=+tasks.value,cap=n*8000,ok=!stateful.checked;visualField.innerHTML='<div class="support-gate">Input → '+(stateful.checked?'keyed state operator → <strong>STOP: unsupported in this lesson’s Spark 4.1 RTM scope</strong>':'stateless filter → <strong>support gate passes</strong>')+'</div><p>Task lanes in the capacity toy:</p><div class="task-lanes">'+Array.from({length:n},(_,i)=>'<span>Task '+(i+1)+'<br>8,000/s</span>').join('')+'</div><p>Incoming '+rate.toLocaleString()+'/s; total service '+cap.toLocaleString()+'/s</p><div class="flow-meter"><span style="width:'+Math.min(100,100*rate/cap)+'%"></span></div><p>'+(!ok?'Capacity is irrelevant until the unsupported operator is removed or a supported mode is selected.':rate>cap?'Queue grows by '+(rate-cap).toLocaleString()+' events each second in this toy.':'All arriving events fit; spare capacity '+(cap-rate).toLocaleString()+'/s.')+'</p><p>Trigger control '+epochMs.value+' ms → toy batching wait '+(+epochMs.value/2)+' ms. This arithmetic is a comparison aid, not a Real-Time Mode latency prediction.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[inputRate,tasks,epochMs,stateful].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const d=+deadlineMs.value,p=+preworkMs.value,s=+downstreamMs.value,remaining=Math.max(0,d-p),hopBudget=propagate.checked?remaining:d,spent=Math.min(s,hopBudget),total=p+spent,success=p<d&&s<=hopBudget&&total<=d,waste=Math.max(0,total-d);world.textContent='Caller budget: '+d+' ms
Spent before child RPC: '+p+' ms
Child budget: '+hopBudget+' ms'+(propagate.checked?' (remaining budget)':' (fresh per-hop timeout)')+'
Child work performed: '+spent+' ms
Caller-visible result: '+(success?'SUCCESS at '+total+' ms':'DEADLINE EXCEEDED')+'
Work after caller budget: '+waste+' ms

'+(propagate.checked?'Expired work is bounded if cancellation is honored.':'A fresh timeout can authorize work after the result is useless.')};[deadlineMs,preworkMs,downstreamMs,propagate].forEach(e=>e.oninput=show);show();
function drawMechanism(){const d=+deadlineMs.value,p=+preworkMs.value,s=+downstreamMs.value,budget=propagate.checked?Math.max(0,d-p):d,spent=Math.min(s,budget),end=p+spent,scale=Math.max(1200,end),pct=x=>100*x/scale;visualField.innerHTML='<p>One ruler, 0–'+scale+' ms. Blue: pre-work. Gold: child work actually performed. Peach line: caller deadline '+d+' ms.</p><div class="deadline-track"><span class="deadline-work" style="width:'+pct(p)+'%"></span><span class="deadline-work deadline-child" style="left:'+pct(p)+'%;width:'+pct(spent)+'%"></span><span class="deadline-mark" style="left:'+pct(d)+'%"></span></div><p>Pre-work: 0 → '+p+' ms. Child: '+p+' → '+end+' ms.</p><p><strong>'+Math.max(0,end-d)+' ms after the caller deadline.</strong> Child budget: '+budget+' ms, '+(propagate.checked?'computed from time left.':'reset to the original timeout.')+'</p><p>'+ (p>=d?'The deadline was already exhausted by pre-work. Skip launching the child.':spent<s?'Child cannot finish its '+s+' ms task within the budget. Cancellation must actually stop the work.':'Child completed its '+s+' ms task; compare its finish with the deadline.')+'</p>';}
const syncMechanism=()=>{show();drawMechanism();};[deadlineMs,preworkMs,downstreamMs,propagate].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const show=()=>{const cap=+capacity.value,c=+critical.value,b=+background.value,total=c+b;let ac,ab;if(total<=cap){ac=c;ab=b}else if(priority.checked){ac=Math.min(c,cap);ab=Math.min(b,Math.max(0,cap-ac))}else{const share=cap/total;ac=Math.floor(c*share);ab=Math.floor(b*share)}const rejected=total-ac-ab;world.textContent='Demand: '+total+' units/s | safe capacity: '+cap+'
Admitted critical: '+ac+'/'+c+'
Admitted background: '+ab+'/'+b+'
Rejected early: '+rejected+'
Policy: '+(priority.checked?'protect critical work first':'proportional sharing')+'
Outcome: '+(total<=cap?'No shedding needed.':ac+ab<=cap?'Capacity remains bounded; the loss is explicit.':'Unsafe admission.')};[capacity,critical,background,priority].forEach(e=>e.oninput=show);show();
function drawMechanism(){const cap=+capacity.value,c=+critical.value,b=+background.value,total=c+b,ac=total<=cap?c:priority.checked?Math.min(c,cap):Math.floor(c*cap/total),ab=total<=cap?b:priority.checked?Math.min(b,Math.max(0,cap-ac)):Math.floor(b*cap/total);const row=(label,d,a)=>'<p>'+label+': '+d+' arrives → '+a+' admitted + '+(d-a)+' rejected</p><div class="admit-row"><span style="width:'+a/2+'%"></span><span class="shed" style="width:'+(d-a)/2+'%"></span></div>';visualField.innerHTML='<p>Admission gate: '+(priority.checked?'critical first':'proportional sharing')+'. Every full ruler represents 200 units/s. Solid = admitted; striped = rejected before service.</p>'+row('Critical',c,ac)+row('Background',b,ab)+'<p>Merge admitted streams → '+(ac+ab)+' / '+cap+' safe units/s.</p><p>'+ (total>cap?'If all '+total+' were admitted, backlog would grow by '+(total-cap)+' units each second. Shedding makes this loss explicit now.':'Demand fits. No rejection is needed.')+'</p><p>Switch policy and watch which stream absorbs the loss. This does not model retries, fairness across tenants, or changing capacity.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[capacity,critical,background,priority].forEach(e=>e.oninput=syncMechanism);drawMechanism();

const run=()=>{let left=+failures.value,turns=0,status='BUDGET_EXHAUSTED',trace=[];if(!evaluator.checked){world.textContent='Turn 1: model reports done.
Outcome: UNVERIFIED SELF-REPORT
No external condition was checked.';return}while(turns<+maxTurns.value){turns++;const before=left;left=Math.max(0,left-+fixRate.value);trace.push('Turn '+turns+': '+before+' → '+left+' failing checks');if(left===0){status='MET';break}if(+fixRate.value===0&&turns===2){status='STALLED';break}}world.textContent=trace.join('
')+'
Outcome: '+status+'
Remaining failures: '+left+'
Synthetic token spend: '+(turns*1200).toLocaleString()+'

end_turn would describe one response; this verdict describes the task contract.'};runLoop.onclick=run;[failures,fixRate,maxTurns,evaluator].forEach(e=>e.oninput=run);run();
function drawMechanism(){let left=+failures.value,turn=0,status='BUDGET_EXHAUSTED',points=[left];if(!evaluator.checked){visualField.innerHTML='<p>Model: “done” → <strong>no evidence gate</strong> → UNVERIFIED SELF-REPORT</p><p>No verified failure count is available. A success-shaped message cannot replace a test result.</p>';return;}while(turn<+maxTurns.value){turn++;left=Math.max(0,left-+fixRate.value);points.push(left);if(left===0){status='MET';break;}if(+fixRate.value===0&&turn===2){status='STALLED';break;}}visualField.innerHTML='<p>Each bar uses the same scale: 10 px per failing check.</p><div class="turn-ledger">'+points.map((v,i)=>'<div class="turn-col"><b>'+v+'</b><span style="height:'+v*10+'px"></span>'+(i?'Turn '+i:'Start')+'</div>').join('')+'</div><div class="stop-verdict"><strong>'+status+'</strong><p>'+(status==='MET'?'The evaluator observed zero remaining failures.':status==='STALLED'?'Two turns made no progress. Preserve the checked state and change strategy.':'Turn budget ran out with '+left+' checks still failing. Preserve this state for a deliberate continuation.')+'</p></div>';}
const syncMechanism=()=>{run();drawMechanism();};[failures,fixRate,maxTurns,evaluator].forEach(e=>e.oninput=syncMechanism);runLoop.onclick=syncMechanism;drawMechanism();

const show=()=>{const n=+gateCount.value,t=+gateNs.value,p=+infidelity.value/100000,zero=100*Math.pow(1-p,n),expected=n*p;world.textContent='Toy sequence: '+n.toLocaleString()+' identical entangling gates
Total gate time: '+(n*t/1000).toFixed(1)+' μs
Expected failures (independent toy): '+expected.toFixed(3)+'
Probability of zero modeled failures: '+zero.toFixed(1)+'%

Default gate time and infidelity are paper simulations, not measurements of fabricated hardware.'};[gateCount,gateNs,infidelity].forEach(e=>e.oninput=show);show();
function drawMechanism(){const n=+gateCount.value,t=+gateNs.value,p=+infidelity.value/100000;let path='';for(let i=0;i<=20;i++){const k=n*i/20,x=45+280*i/20,y=25+140*(1-Math.pow(1-p,k));path+=(i?'L':'M')+x+' '+y+' ';}const end=100*Math.pow(1-p,n);visualField.innerHTML='<p>Independent-error toy: what fraction of sequences have zero modeled failures?</p><svg viewBox="0 0 370 215" role="img" aria-label="Survival falls from 100 percent to '+end.toFixed(1)+' percent after '+n+' gates"><path d="M45 25 V165 H325" stroke="#acc4c9" fill="none"/><path d="M45 95 H325" stroke="#516c76"/><path d="'+path+'" fill="none" stroke="#efc583" stroke-width="3"/><text x="4" y="30" font-size="13">100%</text><text x="9" y="100" font-size="13">50%</text><text x="17" y="169" font-size="13">0%</text><text x="44" y="186" font-size="13">0</text><text x="270" y="186" font-size="13">'+n+' gates</text><text x="95" y="207" font-size="14">Sequence duration: '+(n*t/1000).toFixed(1)+' μs</text></svg><p>End: <strong>'+end.toFixed(1)+'% zero-failure sequences</strong>. Doubling gate count compounds error even with unchanged per-gate quality.</p><p>The paper’s memory/interaction separation motivates the design; this curve does not simulate a qubit, correlated noise, or error correction. Default gate values came from paper simulations.</p>';}
const syncMechanism=()=>{show();drawMechanism();};[gateCount,gateNs,infidelity].forEach(e=>e.oninput=syncMechanism);drawMechanism();
